    + fq.html
    + ctaSec(fill(pick1(C.cta.h2, seed + ':cta'), ctx), para(pick1(C.cta.p, seed + ':ctap'), ctx, seed + ':ctap'))
    + sec(`${S[2]} 다른 지역`, links(SIDO_SGS[si].filter(x => x !== gi).map(x => ({ name: REG.SG[x][2], href: `/${prod.key}/${sd}/${REG.SG[x][1]}/` }))));
  return page({ title: fill(SITE.titles.sigungu, ctx), desc: clip(fill(SITE.descs.sigungu, ctx) + ' ' + fill(pick1(C.hook, seed), ctx), 70, 150), path, prod: prod.key, active: prod.key, toc: 1, top: hero({ crumb: cr.html, h1: fill(pick1(C.h1, seed + ':h1'), ctx), hook: fill(pick1(C.hook, seed + ':hook'), ctx) }), body, ld: [cr.ld, fq.ld] });
