/* ---------- RSS ---------- */
function rfc822(d) {
  const t = new Date(d + 'T00:00:00+09:00');
  const wd = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][t.getUTCDay()];
  const mo = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'][Number(d.slice(5, 7)) - 1];
  return `${wd}, ${d.slice(8, 10)} ${mo} ${d.slice(0, 4)} 00:00:00 +0900`;
}
/* 고정 항목(가이드·형태·업종) + 날짜별로 도는 지역 페이지 40개 */
function rssItems() {
  const it = [];
  C.guides.forEach(g => it.push({ path: `/guide/${g.slug}/`, title: g.title, desc: g.desc }));
  ACTIVE.forEach(p => it.push({ path: `/${p.key}/`, title: fill(SITE.titles.hubH1, { '제품': p.ko }), desc: fill(SITE.descs.hub, { '제품': p.ko }) }));
  ACTIVE.forEach(p => BIZ.forEach(b => it.push({ path: `/${p.key}/biz/${b.slug}/`, title: `${b.ko} ${p.ko}`, desc: fill(SITE.descs.biz, { '업종': b.ko, '제품': p.ko }) })));
  const regions = allUrls().filter(u => u.split('/').filter(Boolean).length >= 3);
  const day = Math.floor(Date.now() / 86400000);
  for (let i = 0; i < 40 && regions.length; i++) {
    const u = regions[(day * 40 + i * 977) % regions.length];
    const seg = u.split('/').filter(Boolean);
    const pr = PRODUCT_MAP[seg[0]];
    const loc = regionLabel(seg[1], seg[2], seg[3]);
    it.push({ path: u, title: `${loc} ${pr ? pr.ko : '카드단말기'}`, desc: `${loc} ${SITE.angleShort} 안내` });
  }
  return it;
}
function rssFeed() {
  const pub = rfc822(BUILD_DATE);
  const items = rssItems().map(x => `<item><title>${esc(x.title)}</title><link>${ORIGIN}${x.path}</link><guid isPermaLink="true">${ORIGIN}${x.path}</guid><pubDate>${pub}</pubDate><description>${esc(x.desc || '')}</description></item>`).join('\n');
  return `<rss version="2.0" xmlns:atom="http://www.w3.org/2005/Atom"><channel>
<title>${esc(SITE.brand)}</title>
<link>${ORIGIN}/</link>
<description>${esc(SITE.llmsSummary)}</description>
<language>ko</language>
<lastBuildDate>${pub}</lastBuildDate>
<atom:link href="${ORIGIN}/rss.xml" rel="self" type="application/rss+xml"/>
${items}
</channel></rss>`;
}

/* ---------- IndexNow ---------- */
async function runIndexNow(url) {
  const urls = allUrls().map(p => ORIGIN + p);
  const force = url && url.searchParams.get('force') === '1';
  const dayIdx = Math.floor(Date.now() / 86400000) % 7;
  const today = force ? urls : urls.filter((_, i) => i % 7 === dayIdx);
  const results = [];
  for (let i = 0; i < today.length; i += 1000) {
    const batch = today.slice(i, i + 1000);
    const body = JSON.stringify({ host: SITE.domain, key: SITE.indexnowKey, keyLocation: ORIGIN + '/' + SITE.indexnowKey + '.txt', urlList: batch });
    const [nv, ix] = await Promise.allSettled([
      fetch('https://searchadvisor.naver.com/indexnow', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body }),
      indexnowFetch({ method: 'POST', headers: { 'Content-Type': 'application/json' }, body }),
    ]);
    results.push({ batch: i / 1000 + 1, size: batch.length, naver: nv.status === 'fulfilled' ? nv.value.status : 'ERR', indexnow: ix.status === 'fulfilled' ? ix.value.status : 'ERR' });
  }
  return { ok: true, totalUrls: urls.length, dayIdx, submitted: today.length, force, results };
}

/* ---------- 라우터 ---------- */
const HTML_H = { 'Content-Type': 'text/html;charset=utf-8', 'Cache-Control': 'public,max-age=3600,s-maxage=86400' };
function html(s) { return new Response(s, { headers: HTML_H }); }

async function handle(request, env, ctx) {
  const url = new URL(request.url);
  const raw = url.pathname;
  const path = raw.replace(/\/+$/, '') || '/';

  if (path === '/api/track' && request.method === 'POST') {
    try {
      const b = await request.json();
      /* 같은 방문자가 같은 버튼을 반복해 눌러도 1건만 기록·발송한다 */
      if (await tkDup(env, SITE.key, b.type, (b.page || '').slice(0, 300), request.headers.get('CF-Connecting-IP') || '')) {
        return new Response(JSON.stringify({ ok: true, dup: 1 }), { headers: { 'content-type': 'application/json', 'access-control-allow-origin': '*' } });
      }
      var __ua = request.headers.get('User-Agent') || '';
      if (!TG_BOT_RE.test(__ua) && TG_LABEL[b.type]) { var __tgp = tgNotify(env, b.type, (b.page || '/').slice(0, 300), b.ref || '', __ua, String(b.b || '').slice(0, 40)); if (ctx && ctx.waitUntil) ctx.waitUntil(__tgp); else await __tgp; }
      const ip = request.headers.get('CF-Connecting-IP') || ''; const ts = new Date().toISOString();
      if (env && env.DB && !(b.type === 'view' && BOT_UA_RE.test(request.headers.get('User-Agent') || '') || (b.type === 'view' && skipViewCf(request, request.headers.get('CF-Connecting-IP') || ''))) && (b.type === 'tel' || b.type === 'sms' || b.type === 'contact' || b.type === 'view')) {
        await env.DB.prepare('INSERT INTO events (site,type,page,ref,ip,ts,ua,device,source,keyword) VALUES (?,?,?,?,?,?,?,?,?,?)')
          .bind(SITE.key, b.type, (b.page || '').slice(0, 300), (b.ref || '').slice(0, 120), ip, ts, ...tkMeta(request.headers.get('User-Agent') || '', b.ref || '', SITE.domain)).run();
      }
    } catch (e) {}
    return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json', 'Access-Control-Allow-Origin': '*' } });
  }
  if (path === '/api/track' && request.method === 'OPTIONS') return new Response(null, { headers: { 'Access-Control-Allow-Origin': '*', 'Access-Control-Allow-Methods': 'POST,OPTIONS', 'Access-Control-Allow-Headers': 'Content-Type' } });
  if (path === '/api/contact' && request.method === 'POST') {
    try {
      const data = await request.json();
      const p = new URLSearchParams();
      Object.keys(data).forEach(k => p.append(k, data[k] || ''));
      const gsUrl = GAS_URL + '?' + p.toString();
      await fetch(gsUrl, { method: 'GET', redirect: 'follow' });
    } catch (e) {}
    return new Response(JSON.stringify({ ok: true }), { headers: { 'Content-Type': 'application/json' } });
  }
  if (path === '/api/indexnow') return new Response(JSON.stringify(await runIndexNow(url), null, 2), { headers: { 'Content-Type': 'application/json' } });
  if (path === '/' + SITE.indexnowKey + '.txt') return new Response(SITE.indexnowKey, { headers: { 'Content-Type': 'text/plain' } });
  if (path.startsWith('/api/')) return new Response('Not Found', { status: 404 });

  if (path === '/robots.txt') return new Response(`User-agent: *\nAllow: /\nDisallow: /api/\n\nSitemap: ${ORIGIN}/sitemap.xml\nSitemap: ${ORIGIN}/rss.xml\n`, { headers: { 'Content-Type': 'text/plain;charset=utf-8', 'Cache-Control': 'public,max-age=86400' } });
  if (path === '/rss.xml') return xml(rssFeed());
  if (path === '/sitemap.xml') {
    const n = Math.ceil(allUrls().length / SM_PART);
    let s = '<sitemapindex xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n';
    for (let i = 1; i <= n; i++) s += `<sitemap><loc>${ORIGIN}/sitemap-${i}.xml</loc><lastmod>${BUILD_DATE}</lastmod></sitemap>\n`;
    return xml(s + '</sitemapindex>');
  }
  const smp = path.match(/^\/sitemap-(\d+)\.xml$/);
  if (smp) {
    const all = allUrls(); const i = parseInt(smp[1], 10);
    const part = all.slice((i - 1) * SM_PART, i * SM_PART);
    if (i < 1 || !part.length) return notFound();
    return xml('<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">\n' + part.map(p => `<url><loc>${ORIGIN}${p}</loc><lastmod>${BUILD_DATE}</lastmod></url>`).join('\n') + '\n</urlset>');
  }
  if (path === '/llms.txt') {
    const t = `# ${SITE.brand} (${ORIGIN})\n\n> ${SITE.llmsSummary}\n\n## 제품별 페이지\n\n${ACTIVE.map(p => `- [${p.ko}](${ORIGIN}/${p.key}/)`).join('\n')}\n\n## 페이지 구성\n\n- 지역별 안내: /{제품}/{시도}/{시군구}/{동}/\n- 업종별 안내: /{제품}/biz/{업종}/\n- 가이드: ${ORIGIN}/guide/\n${C.guides.map(g => `  - [${g.title}](${ORIGIN}/guide/${g.slug}/)`).join('\n')}\n- 전체 목록: ${ORIGIN}/list\n- 사이트맵: ${ORIGIN}/sitemap.xml\n- RSS: ${ORIGIN}/rss.xml\n\n\n## 연락처\n\n- 전화: ${SITE.telView}\n`;
    return new Response(t, { headers: { 'Content-Type': 'text/plain;charset=utf-8', 'Cache-Control': 'public,max-age=86400' } });
  }

  if (path === '/') return html(homePage());
  if (path === '/list') { if (raw !== '/list') return Response.redirect(ORIGIN + '/list', 301); return html(listPage()); }

  /* 페이지 경로는 끝 슬래시로 통일 */
  if (!raw.endsWith('/')) return Response.redirect(ORIGIN + raw + '/' + url.search, 301);
  const seg = path.split('/').filter(Boolean);
  /* 초기 배포 때 쓰던 /card-terminal/ 주소는 첫 형태(유선)로 옮긴다 */
  if (seg[0] === 'card-terminal') return Response.redirect(ORIGIN + '/' + ACTIVE[0].key + '/' + seg.slice(1).map(x => x + '/').join(''), 301);

  if (seg[0] === 'guide') {
    if (seg.length === 1) return html(guideIndex());
    const g = seg.length === 2 && C.guides.find(x => x.slug === seg[1]);
    return g ? html(guidePage(g)) : notFound();
  }
  const prod = ACTIVE_MAP[seg[0]];
  if (!prod) return notFound();
  if (seg.length === 1) return html(productHub(prod));
  if (seg[1] === 'biz') {
    if (seg.length === 2) return html(bizIndex(prod));
    const b = seg.length === 3 && BIZ_MAP[seg[2]];
    return b ? html(bizPage(prod, b)) : notFound();
  }
  if (SIDO_BY[seg[1]] === undefined) return notFound();
  if (seg.length === 2) return html(sidoPage(prod, seg[1]));
  if (SG_BY[seg[1] + '/' + seg[2]] === undefined) return notFound();
  if (seg.length === 3) return html(sigunguPage(prod, seg[1], seg[2]));
  if (seg.length === 4 && DONG_BY[seg[1] + '/' + seg[2] + '/' + seg[3]] !== undefined) return html(dongPage(prod, seg[1], seg[2], seg[3]));
  return notFound();
}

export default {
  async fetch(request, env, ctx) {
    const __blk = blockScraper(request); if (__blk) return __blk;
    /* www 는 루트 도메인으로 모은다 */
    const __h = new URL(request.url).hostname;
    if (__h === SITE.domain && new URL(request.url).protocol === 'http:') { const u = new URL(request.url); return Response.redirect(ORIGIN + u.pathname + u.search, 301); }
    if (__h === 'www.' + SITE.domain) { const u = new URL(request.url); return Response.redirect(ORIGIN + u.pathname + u.search, 301); }
    return handle(request, env, ctx);
  },
  /* 매일 IndexNow 발송 (wrangler.toml [triggers] crons) — 자기 도메인을 fetch 하지 않고 직접 실행한다 */
  async scheduled(event, env, ctx) {
    ctx.waitUntil((async () => {
      try { const r = await runIndexNow(null); console.log('[CRON IndexNow]', new Date().toISOString(), JSON.stringify(r).slice(0, 500)); }
      catch (e) { console.log('[CRON IndexNow] ERROR:', e.message); }
    })());
  },
};
